group = "net.theprogrammersworld"
version = "2.6.1-SNAPSHOT"
description = "Ding Dong, Herobrine calling!"

val paperSpigotVersion = "1.21.1-R0.1-SNAPSHOT"

plugins {
	`java-library`
  id("io.papermc.paperweight.userdev") version "1.7.1"
  id("com.diffplug.spotless") version "6.25.0"
  id("com.github.johnrengelman.shadow") version "8.1.1"
}

repositories {
  mavenCentral()
  maven("https://repo.papermc.io/repository/maven-public/") /* Paper */
  maven("https://maven.elmakers.com/repository/") /* Spigot */
  maven("https://maven.enginehub.org/repo/") /* worldedit, worldguard */
  maven("https://jitpack.io/") /* furplag/relic */
 }

dependencies {
  paperweight.paperDevBundle(paperSpigotVersion)
  compileOnly("io.papermc.paper:paper-api:${paperSpigotVersion}")
  compileOnly("com.sk89q.worldedit:worldedit-bukkit:7.2.14-SNAPSHOT")
  compileOnly("com.sk89q.worldguard:worldguard-bukkit:7.1.0-SNAPSHOT")

  compileOnly("org.projectlombok:lombok:1.18.30")
  annotationProcessor("org.projectlombok:lombok:1.18.30")

  implementation("com.github.furplag:relic:5.1.0")
}

spotless {
  yaml {
    target("src/**/*.yml")
    jackson()
  }
  java {
    removeUnusedImports()
    indentWithSpaces(2)
    trimTrailingWhitespace()
    endWithNewline()
  }
}

java {
  toolchain.languageVersion.set(JavaLanguageVersion.of(21))
}

tasks {
  // Configure reobfJar to run when invoking the build task
  assemble {
    dependsOn(reobfJar)
  }

  compileJava {
    dependsOn(spotlessApply)
    options.encoding = Charsets.UTF_8.name()
    options.release.set(21)
  }
  javadoc {
    options.encoding = Charsets.UTF_8.name()
  }
  processResources {
    filteringCharset = Charsets.UTF_8.name()
    val props = mapOf(
      "name" to project.name,
      "version" to project.version,
      "description" to project.description,
      "apiVersion" to "1.21",
      "paperSpigotVersion" to paperSpigotVersion
    )
    inputs.properties(props)
    filesMatching("plugin.yml") {
      expand(props)
    }
  }

  // reobfJar {}

  shadowJar {
    // helper function to relocate a package into our package
    fun reloc(pkg: String) = relocate(pkg, "net.theprogrammersworld.herobrine.dependency.$pkg")

    // relocate cloud and it's transitive dependencies
    reloc("jp.furplag.sandbox")
  }
}
